const KEY='japon-plan-2026-v1';
const days=Array.from({length:16},(_,i)=>{const n=i+8;const date=new Date(Date.UTC(2026,11,n));const weekday=new Intl.DateTimeFormat('es-MX',{weekday:'long',timeZone:'UTC'}).format(date);const city=n<14?'Tokio':n<17?'Kioto':n<19?'Osaka':'Tokio';const transition=n===14?'Tokio → Kioto':n===17?'Kioto → Osaka':n===19?'Osaka → Tokio':null;return {n,key:`2026-12-${String(n).padStart(2,'0')}`,weekday:weekday.charAt(0).toUpperCase()+weekday.slice(1),city,transition}});
