let activities=load();let cityFilter='Todas';let view='days';let query='';let editId=null;
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function load(){try{const v=JSON.parse(localStorage.getItem(KEY));return Array.isArray(v)?v:structuredClone(seed)}catch{return structuredClone(seed)}}
function save(){localStorage.setItem(KEY,JSON.stringify(activities));$('saved').textContent='Guardado en este navegador';render()}
function statusLabel(s){return {pendiente:'Pendiente',reservar:'Por reservar',reservado:'Reservado'}[s]||'Pendiente'}
function activityCity(a){if(a.day){return days.find(d=>d.n===a.day)?.city||'Tokio'}return /Osaka|Tempozan|Universal|Nakanoshima/.test(a.zone)?'Osaka':/Kioto|Kurama|Moriyama|Higashiyama|Fushimi|Kitayama/.test(a.zone)?'Kioto':'Tokio'}
function filterActivity(a){return !query||`${a.title} ${a.zone} ${a.note}`.toLocaleLowerCase('es').includes(query)}
function cityMatches(d){return cityFilter==='Todas'||d.city===cityFilter||(d.transition&&d.transition.includes(cityFilter))}
function card(a){return `<div class="activity ${a.fixed?'fixed':'draggable'}" ${a.fixed?'':`draggable="true" data-drag="${esc(a.id)}"`}><span class="activity-icon">${a.fixed?'◆':'↗'}</span><div class="activity-main"><div class="activity-title">${esc(a.title)}</div><div class="activity-sub">${esc(a.time)} · ${esc(a.zone)}${a.transit?`<br>${esc(a.transit)}`:''}</div><span class="status ${a.fixed?'fijo':esc(a.status)}">${a.fixed?'Fecha fija':statusLabel(a.status)}</span></div><div class="activity-actions">${a.fixed?'':`<button class="mini-btn" type="button" data-edit="${esc(a.id)}" aria-label="Editar ${esc(a.title)}">Editar</button>`}</div></div>`}
function dayCard(d){const list=activities.filter(a=>a.day===d.n&&filterActivity(a));const byZone={};for(const a of list){const k=a.zone||'Zona por confirmar';(byZone[k]??=[]).push(a)}const contents=Object.entries(byZone).map(([zone,arr])=>`<div class="zone-group">${arr.length>1?`<div class="zone-label">${esc(zone)}</div>`:''}${arr.map(card).join('')}</div>`).join('');return `<article class="day-card" data-day="${d.n}"><div class="day-head"><div class="date-square">${d.n}</div><div class="day-head-copy"><b>${esc(d.weekday)} ${d.n} de diciembre</b><small>${d.transition?esc(d.transition):esc(d.city)}</small></div><span class="city-chip ${d.city.toLowerCase()}">${esc(d.city)}</span></div><div class="activity-list">${contents||'<div class="empty-day">Arrastra aquí una actividad o añade una nueva.</div>'}</div></article>`}
function render(){const selected=days.filter(cityMatches);$('planner').innerHTML=view==='days'?selected.map(dayCard).join(''):['Tokio','Kioto','Osaka'].filter(c=>cityFilter==='Todas'||c===cityFilter).map(c=>`<div class="city-group"><h3>${c}</h3><span>${c==='Tokio'?'8–14 y 19–23':c==='Kioto'?'14–17':'17–19'} de diciembre</span></div>${selected.filter(d=>d.city===c).map(dayCard).join('')}`).join('');const ideas=activities.filter(a=>a.day==null&&filterActivity(a)&&(cityFilter==='Todas'||activityCity(a)===cityFilter));$('ideas').innerHTML=ideas.length?ideas.map(a=>`<article class="idea-card" draggable="true" data-drag="${esc(a.id)}"><div class="idea-top"><span class="city-chip ${activityCity(a).toLowerCase()}">${activityCity(a)}</span><span class="status ${esc(a.status)}">${statusLabel(a.status)}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.zone)} · ${esc(a.transit||'Traslado por confirmar')}</p><div class="idea-actions"><button data-edit="${esc(a.id)}" type="button">Editar</button><button data-edit="${esc(a.id)}" type="button">Elegir día →</button></div></article>`).join(''):'<p class="empty-day">No hay ideas sin fecha con este filtro.</p>';$('pendingCount').textContent=activities.filter(a=>!a.fixed&&a.status!=='reservado').length;document.querySelectorAll('#cityFilters button').forEach(b=>b.classList.toggle('active',b.dataset.city===cityFilter));$('daysViewBtn').classList.toggle('active',view==='days');$('citiesViewBtn').classList.toggle('active',view==='cities')}
function openEdit(id){const a=activities.find(x=>x.id===id);if(!a||a.fixed)return;editId=id;$('dialogTitle').textContent=id==='__new'?'Nueva actividad':'Editar actividad';$('activityTitle').value=a.title;$('activityZone').value=a.zone;$('activityDay').innerHTML=`<option value="">Sin fecha · ideas</option>`+days.map(d=>`<option value="${d.n}">${d.n} dic · ${d.city}${d.transition?' (traslado)':''}</option>`).join('');$('activityDay').value=a.day??'';$('activityTime').value=a.time;$('activityStatus').value=a.status;$('activityTransit').value=a.transit;$('activityNote').value=a.note;$('deleteActivity').classList.toggle('hidden',id==='__new');$('editDialog').showModal();$('activityTitle').focus()}
$('cityFilters').innerHTML=['Todas','Tokio','Kioto','Osaka'].map(c=>`<button type="button" data-city="${c}" class="${c==='Todas'?'active':''}">${c}</button>`).join('');$('cityFilters').addEventListener('click',e=>{const b=e.target.closest('[data-city]');if(b){cityFilter=b.dataset.city;render()}});$('daysViewBtn').onclick=()=>{view='days';render()};$('citiesViewBtn').onclick=()=>{view='cities';render()};$('search').oninput=e=>{query=e.target.value.trim().toLocaleLowerCase('es');render()};document.addEventListener('click',e=>{const b=e.target.closest('[data-edit]');if(b)openEdit(b.dataset.edit)});
$('addBtn').onclick=()=>{const a={id:'__new',title:'',zone:'',day:null,time:'Flexible',status:'pendiente',transit:'',note:'',fixed:false};activities.push(a);openEdit(a.id)};$('closeDialog').onclick=()=>{if(editId==='__new')activities=activities.filter(a=>a.id!=='__new');$('editDialog').close()};$('editDialog').addEventListener('cancel',()=>{if(editId==='__new')activities=activities.filter(a=>a.id!=='__new')});$('editForm').onsubmit=e=>{e.preventDefault();const a=activities.find(x=>x.id===editId);if(!a)return;a.title=$('activityTitle').value.trim();a.zone=$('activityZone').value.trim()||'Zona por confirmar';a.day=$('activityDay').value?Number($('activityDay').value):null;a.time=$('activityTime').value;a.status=$('activityStatus').value;a.transit=$('activityTransit').value.trim()||'Por confirmar';a.note=$('activityNote').value.trim();if(a.id==='__new')a.id='custom-'+Date.now();$('editDialog').close();save()};$('deleteActivity').onclick=()=>{activities=activities.filter(a=>a.id!==editId);$('editDialog').close();save()};
let dragging=null;document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-drag]');if(!el)return;dragging=el.dataset.drag;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragging)});document.addEventListener('dragover',e=>{const day=e.target.closest('[data-day]');if(day&&dragging){e.preventDefault();day.classList.add('drag-over');e.dataTransfer.dropEffect='move'}});document.addEventListener('dragleave',e=>{const day=e.target.closest('[data-day]');if(day&&!day.contains(e.relatedTarget))day.classList.remove('drag-over')});document.addEventListener('drop',e=>{const day=e.target.closest('[data-day]');if(!day)return;e.preventDefault();const id=e.dataTransfer.getData('text/plain')||dragging;const a=activities.find(x=>x.id===id);if(a&&!a.fixed){a.day=Number(day.dataset.day);save()}dragging=null;day.classList.remove('drag-over')});document.addEventListener('dragend',()=>{dragging=null;document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'))});
$('resetBtn').onclick=()=>$('resetDialog').showModal();$('closeReset').onclick=$('cancelReset').onclick=()=>$('resetDialog').close();$('confirmReset').onclick=()=>{activities=structuredClone(seed);localStorage.removeItem(KEY);$('resetDialog').close();render()};render();
